public void UnHookRecv()
{
	if (IsHooked)
	{
		if (RecvAddress != 0)
		{
			Memory.WriteProcessMemory(Memory.Id, RecvAddress, bufferRecv, 10, 0);
		}
		IsHooked = false;
	}
}

RecvAddress = (int)GetRemoteProcAddress(Process.GetProcessById(ProcessId), "ws2_32.dll", "recv");
int read;
if (RecvAddress != 0 && Memory.ReadProcessMemory(Memory.Id, RecvAddress, bufferRecv, 10, out read) && read == 10)
{ PostMessage(ProcessId, -10); IsHooked = true; }

